/// <summary>
/// Handles the posting of purchase order confirmations.
/// </summary>
public class METPurchTableConfirmationService
{
}

Method.Source:
/// <summary>
/// Posts the confirmation for a given purchase order.
/// </summary>
/// <param name = "_purchId"></param>
public static void postConfirmation(PurchId _purchId)
{
    PurchTable purchTable = PurchTable::find(_purchId);
    PurchFormLetter purchFormLetter;
    str confirmationnum;
    if (purchTable.RecId != 0)
    {
        // We should only attempt to post the confirmation if the purchase order is approved and not already invoiced or canceled.
        if(purchTable.isInvoiced() || purchTable.isCanceled() || purchTable.DocumentState != VersioningDocumentState::Approved)
        {
            // If the purchase order is already invoiced, canceled, or not approved, we should not update the workflow status to confirmed.
            return;
        }

        try
        {
            purchFormLetter = PurchFormLetter::construct(DocumentStatus::PurchaseOrder);
            confirmationnum = strFmt('%1-%2', purchTable.PurchId, VendPurchOrderJour::numberOfPurchaseOrderVersions(purchTable) + 1);

            ttsbegin;
            purchFormLetter.initParameters(purchFormLetter.purchParmUpdate(), PrintOut::After);  // Printout
            purchFormLetter.update(purchTable, confirmationnum, systemDateGet(), PurchUpdate::All, AccountOrder::Auto, NoYes::No, NoYes::Yes, NoYes::Yes);
            ttscommit;
        }
        catch (Exception::Error)
        {
            error(strFmt("@MET:METPurchaseOrderConfirmationError", _purchId));
            // Do not throw error if update fails, as the confirmation has already been posted and we don't want to block that.
        }
    }
}
